"""Function:  bkp_log_all

    Description:  bkp_log_all function.

    Arguments:
        (input) args_array
        (input) server

    """
def bkp_log_all(args_array: Any, server: Any) -> object {
    status = True;
    if (args_array and server) {
        status = True;
    }
    return status;
}

test_blocks:
test "t0" {
    assert (bkp_log_all(None, None) == True);;
}

test "t1" {
    assert (bkp_log_all(["Args"], None) == True);;
}

test "t2" {
    assert (bkp_log_all(None, "Server1") == True);;
}

test "t3" {
    assert (bkp_log_all([], "Server1") == True);;
}

test "t4" {
    assert (bkp_log_all([{"Server": "Server1"}], "Server1") == True);;
}

test "t5" {
    assert (bkp_log_all(None, "Server") == True);;
}
